// The bundled deck (generated by `npm run deck:build` from deck/songs.csv).
import deckJson from '../data/deck.json';
import type { Deck, Song } from './game/types';
import { decadeOf } from './game/deck';

export const deck = deckJson as unknown as Deck;
export const songs: Song[] = deck.songs;
export const songsById = new Map(songs.map((s) => [s.id, s]));

export function song(id: string): Song {
  const s = songsById.get(id);
  if (!s) throw new Error(`Unknown song ${id}`);
  return s;
}

export const yearRange = {
  min: Math.min(...songs.map((s) => s.year)),
  max: Math.max(...songs.map((s) => s.year)),
};

const DECADE_COLORS: Record<number, string> = {
  1970: 'var(--d70)',
  1980: 'var(--d80)',
  1990: 'var(--d90)',
  2000: 'var(--d00)',
  2010: 'var(--d10)',
  2020: 'var(--d20)',
};

export function decadeColor(year: number): string {
  return DECADE_COLORS[decadeOf(year)];
}

const FLAGS: Record<string, string> = {
  JP: '🇯🇵',
  US: '🇺🇸',
  IT: '🇮🇹',
  FR: '🇫🇷',
  ES: '🇪🇸',
  BE: '🇧🇪',
  UK: '🇬🇧',
  DE: '🇩🇪',
  CA: '🇨🇦',
  NL: '🇳🇱',
  SE: '🇸🇪',
  AU: '🇦🇺',
};
const COUNTRY: Record<string, string> = {
  JP: 'Giappone',
  US: 'Stati Uniti',
  IT: 'Italia',
  FR: 'Francia',
  ES: 'Spagna',
  BE: 'Belgio',
  UK: 'Regno Unito',
  DE: 'Germania',
  CA: 'Canada',
  NL: 'Paesi Bassi',
  SE: 'Svezia',
  AU: 'Australia',
};

export const flagOf = (origin: string) => FLAGS[origin] ?? '🌍';
export const countryOf = (origin: string) => COUNTRY[origin] ?? origin;
